import { useCallback, useState } from "react";
import { ipc } from "../lib/ipc";
import { persistDocument } from "../services/save";
import type { DocumentSnapshot } from "../contracts/types";
import { loadDraft } from "../lib/drafts/recovery";

export function useDocumentState() {
  const [snapshot, setSnapshot] = useState<DocumentSnapshot | null>(null);
  const [content, setContentState] = useState("# MD Studio\n");
  const [dirty, setDirty] = useState(false);
  const [diagnostics, setDiagnostics] = useState<string[]>([]);
  const [relativePath, setRelativePath] = useState("README.md");

  const setContent = useCallback((v: string) => {
    setContentState(v);
    setDirty(true);
  }, []);

  const openRelative = useCallback(async (path: string) => {
    const ws = await ipc.openWorkspace(".");
    const snap = await ipc.readDocument(ws.id, path);
    const draft = loadDraft(ws.id, path);
    setSnapshot(snap);
    setRelativePath(path);
    setContentState(draft ?? snap.content);
    setDirty(!!draft && draft !== snap.content);
    setDiagnostics(draft ? ["Rascunho de recuperação carregado"] : []);
  }, []);

  const save = useCallback(async () => {
    if (!snapshot) {
      const ws = await ipc.openWorkspace(".");
      const snap = await ipc.readDocument(ws.id, relativePath);
      setSnapshot(snap);
      const result = await persistDocument(snap, content);
      if (!result.ok) {
        setDiagnostics([`Falha ao salvar: ${result.code} — ${result.message}`]);
        return;
      }
      setSnapshot(result.snapshot);
      setDirty(false);
      setDiagnostics(["Salvo"]);
      return;
    }
    const result = await persistDocument(snapshot, content);
    if (!result.ok) {
      setDiagnostics([`Conflito/erro: ${result.code} — ${result.message}`]);
      return;
    }
    setSnapshot(result.snapshot);
    setDirty(false);
    setDiagnostics(["Salvo"]);
  }, [snapshot, content, relativePath]);

  return {
    content,
    setContent,
    dirty,
    diagnostics,
    relativePath,
    openRelative,
    save,
  };
}
